components.css:
.ds-primary { box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; height: 43px; padding: 9.5px 15px; border-radius: var(--radius-md, 2px); font: 400 14px/22px var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); cursor: pointer; transition: background-color .2s, color .2s, border-color .2s; border: 1px solid transparent; background: var(--color-primary, #2443ae); color: #ffffff; }
.ds-primary:hover { background: #4562ba; }
.ds-primary:focus-visible { outline: 2px solid var(--color-primary, #2443ae); outline-offset: 3px; }

.ds-hero { display: inline-flex; align-items: center; box-sizing: border-box; min-height: 46px; padding: 0 21px; color: #ffffff; background: var(--color-primary, #2443ae); border: 1px solid var(--color-primary, #2443ae); border-radius: var(--radius-md, 2px); font: 650 .9375rem/1.65 var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); text-decoration: none; }
.ds-hero:hover { color: #ffffff; background: var(--color-primary-strong, #1b3288); border-color: var(--color-primary-strong, #1b3288); }
.ds-hero:focus-visible { outline: 2px solid var(--color-primary, #2443ae); outline-offset: 3px; }

.ds-secondary { box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; height: 43px; padding: 9.5px 15px; border-radius: var(--radius-md, 2px); font: 400 14px/22px var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); cursor: pointer; transition: background-color .2s, color .2s, border-color .2s; background: var(--color-surface, #fdfbf6); color: var(--color-text, #202019); border: 1px solid var(--color-border, #cdc7b9); border-radius: var(--radius-md, 2px); }
.ds-secondary:hover { border-color: #4562ba; color: #4562ba; }
.ds-secondary:focus-visible { outline: 2px solid var(--color-primary, #2443ae); outline-offset: 3px; }

.ds-input { box-sizing: border-box; height: 43px; padding: 9.5px 11px; background: var(--color-surface, #fdfbf6); color: var(--color-text, #202019); border: 1px solid var(--color-border, #cdc7b9); border-radius: var(--radius-md, 2px); font: 400 14px/22px var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); transition: border-color .2s; }
.ds-input::placeholder { color: var(--color-text-tertiary, #6b6658); opacity: 1; }
.ds-input:hover, .ds-input:focus { border-color: #4562ba; }
.ds-input:focus-visible { outline: 2px solid var(--color-primary, #2443ae); outline-offset: 3px; }

.ds-categories { display: flex; flex-wrap: wrap; gap: 8px; }
.ds-categories button { min-height: 36px; padding: 5px 11px; border: 1px solid var(--color-border, #cdc7b9); border-radius: var(--radius-md, 2px); color: var(--color-text, #202019); background: transparent; font: 400 .84rem/1.57 var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); cursor: pointer; }
.ds-categories button:hover { color: #4562ba; border-color: #4562ba; }
.ds-categories button[aria-pressed="true"] { color: var(--color-surface, #fdfbf6); border-color: var(--color-text, #202019); background: var(--color-text, #202019); }
.ds-categories button:focus-visible { outline: 2px solid var(--color-primary, #2443ae); outline-offset: 3px; }

.ds-nav { display: flex; flex-wrap: wrap; gap: 0 clamp(10px, 2vw, 23px); border-bottom: 1px solid var(--color-border, #cdc7b9); font: 400 .9375rem/1.65 var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); }
.ds-nav a { display: inline-flex; align-items: center; min-height: 44px; padding-inline: 2px; color: var(--color-text-secondary, #625f53); text-decoration: none; white-space: nowrap; }
.ds-nav a:hover, .ds-nav a[aria-current="page"] { color: var(--color-primary, #2443ae); }
.ds-nav a[aria-current="page"] { box-shadow: inset 0 -2px currentColor; font-weight: 650; }
.ds-nav a:focus-visible { outline: 2px solid var(--color-primary, #2443ae); outline-offset: 3px; }

.ds-panel { background: var(--color-surface, #fdfbf6); color: var(--color-text, #202019); border: 1px solid var(--color-border, #cdc7b9); border-radius: var(--radius-md, 2px); padding: clamp(18px, 2.3vw, 32px); font: 400 .9375rem/1.65 var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); }
.ds-panel h2 { margin: 0 0 16px; font: 750 clamp(1.25rem, 2vw, 1.7rem)/1.24 var(--font-display, "Noto Serif SC Variable", "Songti SC", SimSun, Georgia, serif); letter-spacing: -.04em; }
.ds-panel p { margin: 0; color: var(--color-text-secondary, #625f53); }

.ds-brief { color: var(--color-text, #202019); font: 400 .9375rem/1.65 var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); }
.ds-brief label { display: block; margin-bottom: 8px; font-weight: 650; }
.ds-brief textarea { box-sizing: border-box; display: block; width: 100%; min-height: 182px; padding: 16px 18px; background: var(--color-surface, #fdfbf6); color: var(--color-text, #202019); border: 1px solid var(--color-border, #cdc7b9); border-radius: var(--radius-md, 2px); font: inherit; resize: vertical; }
.ds-brief textarea::placeholder { color: var(--color-text-tertiary, #6b6658); opacity: 1; }
.ds-brief textarea:hover { border-color: var(--color-primary, #2443ae); }
.ds-brief textarea:focus-visible { outline: 2px solid var(--color-primary, #2443ae); outline-offset: 3px; }

.ds-delivery { padding-top: 16px; border-top: 3px solid var(--color-primary, #2443ae); color: var(--color-text, #202019); font: 400 .9375rem/1.65 var(--font-body, "Plus Jakarta Sans Variable", "Microsoft YaHei UI", "PingFang SC", sans-serif); }
.ds-delivery h2 { margin: 0 0 20px; color: var(--color-primary, #2443ae); font: 750 clamp(1.3rem, 2.2vw, 1.75rem)/1.24 var(--font-display, "Noto Serif SC Variable", "Songti SC", SimSun, Georgia, serif); letter-spacing: -.04em; }
.ds-delivery dl, .ds-delivery dd { margin: 0; }
.ds-delivery dl > div { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; padding-block: 10px; border-bottom: 1px solid var(--color-border, #cdc7b9); }
.ds-delivery dt { color: var(--color-text-secondary, #625f53); }
.ds-delivery dd { text-align: end; }
